module.exports = [
{"id":"chaofangbianmian","name":"炒方便面","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/炒方便面/炒方便面.png","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"789 大卡","time":"","servings":"1人份","description":"这道炒方便面口感 Q 弹筋道，咸香入味，是一道改良自传统煮面的家常快手主食。搭配鸡蛋和火腿肠，丰富了蛋白质和能量来源。做法简单，只需注意冷水冲面保持口感，新手也能轻松完成，全程大约 15 分钟即可出锅。","tags":["新手友好"],"ingredients":[{"name":"方便面用量为","amount":"1 包/人。","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡蛋的用量为","amount":"1 个/人。","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"火腿肠的用量为","amount":"1 个/人。","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"食用油的用量为","amount":"10 - 18 ml / 人。","optional":false,"amountValue":18,"amountUnit":"ml"}],"steps":[{"text":"将火腿肠撕开包装，切成宽度 1cm 的小块。","group":"火腿肠预处理"},{"text":"向煮锅中加入 1200 ml 水，实际以没过面饼为准。完全煮沸，不要在未沸腾时加面。","group":"面的处理"},{"text":"加入方便面面饼，煮 45 秒。煮的过程中将其挑动，把面条打散。","group":"面的处理"},{"text":"面条打散后立刻关火。不要煮熟！","group":"面的处理"},{"text":"从锅中舀出 80ml 热面汤备用。","group":"面的处理"},{"text":"将面汤和面分离。用凉水冲一下面条。","group":"面的处理"},{"text":"沥干面条上的水分。不要长时间将面泡在水中。","group":"面的处理"},{"text":"准备一个小碗，将方便面的调料包挤进去。","group":"酱料处理"},{"text":"挤进去所有菜包","group":"酱料处理"},{"text":"挤进去所有酱包","group":"酱料处理"},{"text":"挤进去 50% - 80% 的粉包。（全部粉包都挤进去会很咸）","group":"酱料处理"},{"text":"将上一步的 80ml 热面汤全部倒入小碗，搅匀，得到调料碗。","group":"酱料处理"},{"text":"取出计算好的数量的鸡蛋，打入一个小碗。不要加盐！（鸡蛋最终会混合锅里食材的盐味）","group":"鸡蛋的预处理"},{"text":"热锅 20s，加入份数 * 8ml 油。","group":"鸡蛋的预处理"},{"text":"加入刚刚准备好的一碗鸡蛋。翻炒大约 20s 至鸡蛋形成固态即可。","group":"鸡蛋的预处理"},{"text":"将煎鸡蛋取出暂存。不需要洗锅。但一般锅内不会残余太多油。","group":"鸡蛋的预处理"},{"text":"重新热锅 20s，向锅内加入油：份数 * 10ml。","group":"最终步骤"},{"text":"加入第一步处理的火腿肠。翻炒 10 秒。","group":"最终步骤"},{"text":"加入第二步的面。翻炒 30 秒。","group":"最终步骤"},{"text":"加入第三步的调料碗。翻炒 30 秒。","group":"最终步骤"},{"text":"加入第四步的煎鸡蛋。翻炒 30 秒。","group":"最终步骤"},{"text":"关火盛盘即可。","group":"最终步骤"}],"tips":["在北京，可以考虑在盛盘后加入芝麻酱。如果芝麻酱太浓稠，可以 1:1 兑水稀释。","必须使用冷水冲面条！冷水能瞬间剥离面条表面的糊化淀粉，并强制中断内部的余温加热，这是保证面条下锅炒不坨、不粘锅、保持 Q 弹的核心原理。","处理面条的另一种方案，同样可以让面条劲道弹牙。拉长了面条整体处理时间，可以同步准备其他辅料：","洗面：将方便面面饼放入凉水中浸泡 2 分钟，使其完全吸收水分变湿润，捞出沥干（不用泡软）。","上蒸：将湿面饼放入蒸锅，水开后大火蒸 8 分钟，取出抖散备用（蒸能锁住水分，保证面条弹牙）。"]},
{"id":"chaohefen","name":"炒河粉","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"822 大卡","time":"","servings":"1人份","description":"炒河粉是一道流行于广东地区的经典小吃，讲究镬气十足、干香爽滑，河粉软韧透亮，搭配肉丝、豆芽和黄瓜丝，口感层次丰富。主要提供碳水化合物和蛋白质，蔬菜的加入也补充了维生素与膳食纤维。按本菜谱操作难度适中，即便新手只要备齐材料也能尝试，整个制作过程约需 30 分钟即可端上餐桌。","tags":["进阶挑战"],"ingredients":[{"name":"河粉用量为","amount":"250 g/人，如果需要更大食量，可再加 100g/人 向下取整。","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"黄瓜丝","amount":"30g/人、面筋块 30g/人、绿豆芽 30g/人、打碎的鸡蛋 1 个/人。","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"拍碎的蒜瓣","amount":"2 个/人、小葱 1 根/人","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"河粉料可按","amount":"20g/人添加，若自行准备炒料可 10g 盐+2g 味精+3g 孜然粉。","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"淀粉可准备每","amount":"100g 肉+5g 淀粉比例准备。","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"老抽/生抽，分别为每","amount":"250g 河粉 10ml/15ml。","optional":false,"amountValue":250,"amountUnit":"g"}],"steps":[{"text":"小葱切碎（葱白和葱叶分开）、蒜瓣拍碎，丢案板上备用。","group":"准备工作"},{"text":"打碎鸡蛋，捞一点蛋清到一只碗中，剩下的丢入另一只碗中备用。","group":"准备工作"},{"text":"将绿豆芽放入锅中，大火煮 60 秒。豆芽捞出，过凉水，放入盘中备用。","group":"准备工作"},{"text":"黄瓜切丝放入盘中备用，可和豆芽丢一起。","group":"准备工作"},{"text":"处理面筋，单独丢一个盘中。","group":"准备工作"},{"text":"肉切细条状，加入淀粉与刚刚碗中的鸡蛋清、胡椒粉，顺时针拌匀。","group":"准备工作"},{"text":"注：超市购买来的凉皮表面一般会有食用油，可以使用自来水清洗。面筋同样。","group":"准备工作"},{"text":"注：清洗面筋之后，请用手将面筋中的大量水分挤出（不需过于用力）。","group":"准备工作"},{"text":"加入食用油，锅热倒出。","group":"热锅炒肉"},{"text":"倒入处理好的肉，翻炒均匀至变色，倒入碗中备用。","group":"热锅炒肉"},{"text":"趁锅热，加入 20g 食用油（高血压人群可降低用量），倒入葱白、蒜爆炒出香。","group":"炒制河粉"},{"text":"加入河粉，淋入老抽提色，翻炒均匀后再加入河粉炒料，继续翻炒。","group":"炒制河粉"},{"text":"河粉即将透明时，放入炒制好的肉丝与面筋，并加入生抽提鲜，简单翻炒两次。","group":"炒制河粉"},{"text":"加入豆芽与黄瓜丝，翻炒至河粉完全透明。","group":"炒制河粉"},{"text":"关火！","group":"炒制河粉"},{"text":"撒入葱叶点缀，把锅端起。","group":"最终步骤"},{"text":"倒入盘中，开始干饭。","group":"最终步骤"}],"tips":["个人口味根据地区、天气、时间均有不同，调料的具体使用量请据个人情况而定，喜欢辣椒的可以自行添加。"]},
{"id":"chaoliangfen","name":"炒凉粉","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/炒凉粉/炒凉粉成品.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"567 大卡","time":"15分钟","servings":"1人份","description":"炒凉粉是一道山西、陕西地区的特色小吃，入口滑嫩，咸香微辣，带着蒜香和酱香。凉粉主要由淀粉制成，能提供丰富的碳水化合物，快速补充能量。烹饪难度适中，适合有一定基础的新手尝试，全程制作大约需要 15 分钟。","tags":["辣"],"ingredients":[{"name":"凉粉","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"玉米油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"蒜末","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"香葱","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"豆瓣酱","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"生抽","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"老抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"食盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"十三香","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"中粗辣椒面","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"矿泉水","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"}],"steps":[{"text":"凉粉改刀切麻将块大小","group":""},{"text":"开小火，起锅烧油，锅烧微热后，下入蒜末爆香后加入豆瓣酱炒出红油","group":""},{"text":"将凉粉块下入锅中，翻炒 10 秒","group":""},{"text":"加入生抽提味，老抽上色，翻炒均匀后加入辣椒面继续翻炒均匀","group":""},{"text":"加入食盐、十三香继续翻炒 10 秒","group":""},{"text":"加入准备好的矿泉水，再次翻炒 10 秒，待汤汁浓稠后，关火出锅装盘","group":""},{"text":"撒上葱花即可完成","group":""}],"tips":["选择凉粉时最好选用豌豆淀粉制作成的凉粉，条件不允许的话红薯淀粉或其他也可"]},
{"id":"chaomo","name":"炒馍","category":"主食","categoryKey":"staple","emoji":"🫓","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"767 大卡","time":"","servings":"1人份","description":"炒馍是一道咸香酥脆的家常面食，属于北方风味。馒头丁炒至金黄，外脆里软，孜然与五香粉的加入让风味更加浓郁。可搭配鸡蛋提供蛋白质，搭配小葱增添清香，营养均衡。制作难度适中，新手也能很快上手，预计 大约 15 分钟即可出锅享用。","tags":["辣"],"ingredients":[{"name":"馒头","amount":"2 个（隔天略硬更好）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"油","amount":"20ml（花生油或芝麻油更好）","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"孜然粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"辣椒粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"五香粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"小葱","amount":"2 棵","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡蛋 （可选,2 个）","amount":"","optional":true,"amountValue":null,"amountUnit":""}],"steps":[{"text":"将馒头切成小块或小片。","group":""},{"text":"选有鸡蛋的话将鸡蛋打进碗里，打散（可加盐和五香粉各 1g 或不加，等炒的过程中加）。","group":""},{"text":"鸡蛋浇在馒头上，拌匀，鸡蛋不宜过多。","group":""},{"text":"大火热锅，倒入食用油（不锈钢锅怕伤锅的话可以先倒油，烧至油热也可也可）","group":""},{"text":"将馍丁放进去翻炒，翻炒均匀。","group":""},{"text":"将火调小，炒至馍丁呈金黄色。","group":""},{"text":"放入盐，胡椒粉，五香粉。","group":""},{"text":"最后将葱花放入一起翻炒几下。","group":""},{"text":"关火出锅。","group":""}],"tips":["炒的过程中要注意控制火候，以防炒糊","火大补救措施将火调小，可沿锅边加油润锅或洒水，注意不要全倒在一个地方，最好分散开","调味料可根据个人喜好放入其他香料（比如南德调味料）","如果喜欢吃脆的，可以将火开到最小，多翻炒一会，关火后趁锅热再放置一会再倒出，更香脆","辅料也可根据个人口味方位蒜末，蒜苗等，可以单独爆香在混合"]},
{"id":"chaoniangao","name":"炒年糕","category":"主食","categoryKey":"staple","emoji":"🍮","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"960 大卡","time":"30分钟","servings":"1人份","description":"这是一道闽南风味的主食，年糕软糯弹牙，带着葱油的焦香，家常又饱腹。以米粉制成的年糕提供充足碳水化合物，搭配鸡蛋和青菜能补充蛋白质与维生素，营养均衡。做法简单，对新手友好，从准备到出锅大约需要 30 分钟。","tags":[],"ingredients":[{"name":"年糕","amount":"250 g * 份数","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"小葱","amount":"2 根 * 份数","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"食用油","amount":"50 ml","optional":false,"amountValue":50,"amountUnit":"ml"},{"name":"酱油","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"盐","amount":"1-2g * 份数，按口味喜好。","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"锅中加水烧开，煮熟年糕，碗中加水确保年糕不会粘连，捞起年糕备用。","group":""},{"text":"小葱切葱花（将葱白和葱叶分开），青菜切小段备用。","group":""},{"text":"（可选） 制作炒蛋，见[西红柿炒蛋](https://github.com/Anduin2017/HowToCook/blob/master/dishes/vegetable_dish/%E8%A5%BF%E7%BA%A2%E6%9F%BF%E7%82%92%E9%B8%A1%E8%9B%8B.md)。","group":""},{"text":"热锅，加入 30ml 食用油。","group":""},{"text":"将葱白倒入锅中，直至大部分葱白变成焦黄色且发出香味，倒出葱油备用。","group":""},{"text":"重新热锅，加入 20ml 食用油。","group":""},{"text":"加入所有辅料（鸡蛋，青菜等），翻炒均匀。","group":""},{"text":"将年糕的水倒掉，向锅中加入年糕。","group":""},{"text":"加入酱油和盐，翻炒均匀。","group":""},{"text":"关火，加入葱油，翻炒均匀，乘盘。","group":""}],"tips":["辅料的选择可以根据个人选择酌情添加，如加入瘦肉等","在煮年糕的时候注意搅拌，以免粘锅"]},
{"id":"chaoyidalimian","name":"炒意大利面","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/炒意大利面/a.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"406 大卡","time":"30分钟","servings":"1人份","description":"这道炒意大利面软糯爽口，搭配肥牛和酱料，酱香浓郁，是带有西式风味的家常主食。富含碳水化合物与蛋白质，能快速补充能量。做法简单，新手也能轻松掌握，全程大约需要 30 分钟。","tags":[],"ingredients":[{"name":"意大利面","amount":"50 克 / 人","optional":false,"amountValue":null,"amountUnit":""},{"name":"肥牛","amount":"5 片 / 人","optional":false,"amountValue":5,"amountUnit":"片"},{"name":"食用油","amount":"5ml / 50 克意面","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"加入 250 克水 / 人","group":""},{"text":"待水烧开，下入面条，中火煮 15 - 20 分钟（这个面通常比较硬，捞起来之前最好尝一下，中心如果有一点硬，需要继续煮）","group":""},{"text":"捞出面条，盛入盘中备用","group":""},{"text":"热锅倒入食用油，待油温中热，下入面条翻炒一分钟（如果太干，加入少量水）","group":""},{"text":"放入 10 克番茄酱、肥牛、加入 2g 食盐，继续翻炒一分钟","group":""},{"text":"起锅","group":""}],"tips":[]},
{"id":"congyoubanmian","name":"葱油拌面","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":2,"difficultyText":"★★","calories":"355 大卡","time":"","servings":"1-2人份","description":"葱油拌面是一道经典的上海家常面点，以独特的葱油香味著称，做法简单快捷。富含碳水化合物和脂肪，能快速补充能量。一般初学者只需 20 分钟即可完成，非常适合作为日常快手晚餐。","tags":["新手友好"],"ingredients":[{"name":"小葱","amount":"100 g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"食用油","amount":"100 ml","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"生抽","amount":"60 ml","optional":false,"amountValue":60,"amountUnit":"ml"},{"name":"老抽","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"白糖","amount":"15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"干面条","amount":"80 g （约相当于 150 g 湿面条）","optional":false,"amountValue":80,"amountUnit":"g"},{"name":"葱油酱汁","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"}],"steps":[{"text":"将 小葱 洗净，切成长段（约 5-7 cm）。葱白和葱绿可以分开。","group":"制作葱油酱汁"},{"text":"锅中加入 100 ml 食用油，中火烧热。先放入葱白段，煸炒至微黄。","group":"制作葱油酱汁"},{"text":"加入葱绿段，转小火，继续煸炒。","group":"制作葱油酱汁"},{"text":"保持小火，耐心煸炒约 **15-20 分钟**，直至葱段变得焦黄酥脆。","group":"制作葱油酱汁"},{"text":"将焦黄的葱段捞出（葱油保留在锅中）。","group":"制作葱油酱汁"},{"text":"在锅中的葱油中，加入 60 ml 生抽，20 ml 老抽，15 g 白糖。小火加热并搅拌，约 **1 分钟**，至糖溶解，酱汁混合均匀。立即关火。将制作好的葱油酱汁倒入容器中，放凉后密封保存。","group":"制作葱油酱汁"},{"text":"取 80 g 干面条。","group":"煮面条 （按份操作）"},{"text":"锅中加入 1000 ml 饮用水，大火烧开。","group":"煮面条 （按份操作）"},{"text":"放入 面条，根据面条包装说明，煮至熟透（通常 **3-8 分钟**，以包装说明为准）。","group":"煮面条 （按份操作）"},{"text":"将 煮好的 面条 捞出，沥干水分，放入碗中。","group":"煮面条 （按份操作）"},{"text":"在装有 面条 的碗中，加入 15 ml 之前做好的 葱油酱汁。","group":"混合拌面 （按份操作）"},{"text":"可以加入之前炸好的葱段（可选）。","group":"混合拌面 （按份操作）"},{"text":"用 筷子 快速搅拌均匀，即可食用。","group":"混合拌面 （按份操作）"}],"tips":["炸葱油时，火一定要小，要有耐心，才能将葱的香味充分炸出。","制作好的葱油酱汁可以冷藏保存一段时间，下次吃面时直接取用。"]},
{"id":"danbaofan","name":"蛋包饭","category":"主食","categoryKey":"staple","emoji":"🥚","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"695 大卡","time":"","servings":"1人份","description":"以嫩滑蛋皮包裹茄汁炒饭，口感丰富，酸甜开胃，是一道经典的日式家庭料理。富含蛋白质、碳水和多种维生素，营养均衡。包裹蛋皮需要一点技巧，但整体难度适中，新手也可尝试，从准备到完成约需 25 分钟。","tags":[],"ingredients":[{"name":"鸡蛋","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"洋葱","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"胡萝卜","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"火腿肠或鸡胸肉","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"玉米粒和青豆总共","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"米饭","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"番茄酱","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"食用油","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"牛奶","amount":"10ml（与鸡蛋混合）","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"洋葱、胡萝卜、火腿肠或鸡胸肉切成小丁，备用","group":""},{"text":"热锅，锅中倒入 10ml 食用油，等待 10 秒加热","group":""},{"text":"先放入洋葱丁翻炒 1 分钟，出香味后加入胡萝卜、玉米粒、青豆继续翻炒 2 分钟","group":""},{"text":"加入火腿肠或鸡胸肉丁，炒至变色","group":""},{"text":"加入米饭炒散后，加入番茄酱 20ml，翻炒均匀，炒饭完成，盛出备用","group":""},{"text":"鸡蛋打散，加入 10ml 牛奶搅匀","group":""},{"text":"锅中放入 5ml 食用油，倒入蛋液，轻晃锅底让蛋液均匀铺满锅面","group":""},{"text":"用小火加热，待蛋液表面半熟状态时，将炒饭放入蛋液中央","group":""},{"text":"用铲子将蛋皮折叠包住米饭，形成椭圆形状","group":""},{"text":"用锅铲轻轻推至盘中，整理外形，可在表面挤上少量番茄酱装饰","group":""}],"tips":["炒饭用隔夜饭不易粘锅，口感更好。","打蛋时加入牛奶可以让蛋皮更加嫩滑。","操作蛋皮时火力需小，避免底部焦糊。","如果不擅长包裹造型，也可以直接将炒饭铺盘后盖上蛋皮。"]},
{"id":"danchaofan","name":"蛋炒饭","category":"主食","categoryKey":"staple","emoji":"🥚","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"853 大卡","time":"25分钟","servings":"1人份","description":"一道家常蛋炒饭，金黄的蛋丝裹着粒粒分明的米饭，搭配火腿、胡萝卜和黄瓜，口感丰富，咸香适口。鸡蛋提供优质蛋白，胡萝卜增添维生素，碳水化合物带来充足能量。制作步骤稍多，但新手按流程操作也能成功，全程大约需要 25 分钟。","tags":[],"ingredients":[{"name":"冷饭（份数*500ml）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡蛋 （份数*1.5 //","amount":"1 向下取整）","optional":false,"amountValue":null,"amountUnit":""},{"name":"火腿（份数*2 个）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"黄瓜（可选，份数*30g）","amount":"","optional":true,"amountValue":null,"amountUnit":""},{"name":"胡萝卜（可选，份数*30g）","amount":"","optional":true,"amountValue":null,"amountUnit":""},{"name":"油（份数*12ml）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐（份数\\*4g - 份数*6g）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"胡椒粉（份数*8g）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香葱（份数*1 颗）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽（份数*10ml）","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"米饭提前用铲子铲成小块","group":""},{"text":"火腿肠、胡萝卜、黄瓜等根据需求切片或者块状","group":""},{"text":"如果家里有熟肉 准备好味道更佳","group":""},{"text":"将蛋白，蛋黄分开，分别打入一个大碗里，各自搅匀。注意，不要在这一步加盐。","group":""},{"text":"大火热锅，待锅里冒烟放入食用油，放入蛋白，待主体凝固后盛出备用。","group":""},{"text":"如果油够，则直接放入蛋黄，如果油不够则放入食用油并等其升温到大火热锅","group":""},{"text":"待主体凝固后，将火调至中小火，倒入火腿肠、熟肉，胡萝卜、黄瓜等备料、翻炒 10 秒钟（到爆香）","group":""},{"text":"重新倒入蛋白，翻炒 5s 钟，迅速倒入米饭大火翻炒，为的就是每一粒饭都裹上鸡蛋。","group":""},{"text":"翻炒过程中将米饭的块状捣碎、这一步过程会比较长、待米饭全部捣碎再翻炒均匀即可","group":""},{"text":"调至小火、加盐、胡椒粉、生抽","group":""},{"text":"进一步翻炒均匀，能看到一些米饭在锅里有“跳起来”的时候其实就已经差不多了","group":""},{"text":"最后倒入香葱再翻炒 10s","group":""},{"text":"关火、盛入碗中","group":""}],"tips":["技术总结","使用隔夜的冷饭炒饭最佳，没有冷饭的同学也可以现煮（可以使用冰箱立马给米饭降温），不过要做到“粒粒分明”的口感就需要炒更久。","炒饭要做到“粒粒分明”其实就是要将饭炒干。为什么要用隔夜的冷饭是因为隔夜已经流失了一定的水分。"]},
{"id":"dianfanbaosanwenyuchuifan","name":"电饭煲三文鱼炊饭","category":"主食","categoryKey":"staple","emoji":"🐟","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/电饭煲三文鱼炊饭/电饭煲三文鱼炊饭.webp","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"889 大卡","time":"","servings":"1人份","description":"这是一道融合日式炊饭做法的家常料理，米饭吸饱牛油和三文鱼的香气，口感浓郁鲜香。三文鱼提供优质蛋白和不饱和脂肪酸，搭配菌菇更添膳食纤维。操作极其简单，只需用电饭煲一键完成，从备料到出锅大约 45 分钟，非常适合新手尝试。","tags":["汤","新手友好"],"ingredients":[{"name":"米","amount":"50g / 人","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"三文鱼","amount":"300g / 人","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"水","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"牛油一汤匙 / 人","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"三文鱼去鳞，去骨","group":""},{"text":"金菇、冬菇切碎","group":""},{"text":"洗米三次","group":""},{"text":"把三文鱼、米、牛油放入电饭煲","group":""},{"text":"想口感浓厚一点，可以加多一汤匙牛油","group":""},{"text":"根据电饭煲的刻度放水","group":""},{"text":"把电饭煲調較至煲飯模式，等待大約 30 - 45 分鐘","group":""}],"tips":[]},
{"id":"dianfanbaozhengmifan","name":"电饭煲蒸米饭","category":"主食","categoryKey":"staple","emoji":"🍚","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/米饭/rice_regularPot.jpeg","hasImage":true,"difficulty":1,"difficultyText":"★","calories":"442 大卡","time":"","servings":"1人份","description":"一道家喻户晓的基础主食，米香纯粹、口感软糯，因水量调节可偏硬或偏润。富含碳水化合物，能快速补充能量，适合搭配各类菜肴。操作极其简单，新手也能轻松上手，从洗米到焖好大约需要四十分钟。","tags":["汤","蒸","新手友好"],"ingredients":[{"name":"一般一个人可以食用","amount":"100ml-200ml 的米。","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"江南米，米和水放在电饭煲的容器内，食指触及米时，水量能刚好没过食指的第一个指节又第二个指节","amount":"1/4 处（即大约 2.6 厘米）。","optional":false,"amountValue":null,"amountUnit":""},{"name":"北方大米，米和水放在电饭煲的容器内，食指触及米，水量能刚好没过食指的第一个指节（即大约","amount":"2 厘米处）。","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"清洗米","group":""},{"text":"将米和水一起加入电饭煲中。","group":""},{"text":"连接电饭煲电源，进入加热模式。等待大约 30 分钟。","group":""},{"text":"待电饭煲自动进入保温模式后。","group":""},{"text":"将米在电饭煲中闷 10-15 分钟。","group":""},{"text":"盛出米。","group":""}],"tips":["技术总结","不论什么容器，水的量都是可以使用“指尖量水法”煮出好米饭。","水的多少是能够严重影响一碗好米饭的口感。","南方一般食用江南米，北方一般食用北方大米，江南米会比较细长，而北方大米会比较短且圆。","米饭不同品种的米，不同的水量会极度影响口感。","更多信息请参考使用的电饭煲的说明书。"]},
{"id":"doujiaomenmian","name":"豆角焖面","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"1386 大卡","time":"","servings":"1人份","description":"豆角焖面是一道北方家常面食，面条吸饱汤汁，口感软韧咸香，带着豆角的清爽和肉片的油润。五花肉提供蛋白质和脂肪，豆角富含膳食纤维和维生素，荤素搭配均衡。整体操作不难，但需要留意火候和加汤时机，适合有一定下厨经验的朋友尝试，一般约 30 分钟就能端上桌。","tags":[],"ingredients":[{"name":"鲜面条","amount":"300g。","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"肉","amount":"100g。","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"豆角","amount":"150g。","optional":false,"amountValue":150,"amountUnit":"g"},{"name":"盐的用量为：2g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油的用量为","amount":"10 - 18 ml。","optional":false,"amountValue":18,"amountUnit":"ml"},{"name":"鸡精的用量为：2g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽的用量为：10ml。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"耗油的用量为：5g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"十三香的用量为：1g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽的用量为：5ml。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"味精的用量为：1g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"热水的用量为：150ml。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱","amount":"10g。","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"姜","amount":"5g。","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"蒜","amount":"10g。","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"将豆角切成 5cm - 6cm 的小段。","group":"准备动作"},{"text":"将葱切成 1cm - 2cm 小段。","group":"准备动作"},{"text":"将姜切成 1mm x 1mm x 3cm 的长条","group":"准备动作"},{"text":"将蒜放在砧板上拍碎，切成 1mm 的粒度。","group":"准备动作"},{"text":"将五花肉切成 2mm 厚度的肉片。","group":"准备动作"},{"text":"首先将锅烧热，烧去锅内全部水汽，手放过内距离锅底 10cm 处，感觉明显有些许烤手。","group":"准备动作"},{"text":"加入上述定量的食用油，手持锅柄，离灶 5cm 处，摇晃锅，使食用油充分挂满锅的三分之二（自下而上）。","group":"准备动作"},{"text":"放入全部的姜和全部的葱段，翻炒爆香 5 秒（注意！此时有油飞溅的危险，建议带上手套或做好防护措施）。","group":"准备动作"},{"text":"放入全部的肉片，放入以后不着急饭锅，静置 5 秒后，再翻炒，使所有的肉都裹满食用油。","group":"准备动作"},{"text":"不断翻炒肉片，待到全部肉片都已经变色，沿锅边均匀淋如准备好的生抽，翻炒均匀。","group":"准备动作"},{"text":"依次加入准备好的盐、老抽、耗油、十三香、鸡精以及全部准备好的豆角，翻炒 2 分钟。","group":"准备动作"},{"text":"加入准备好的热水。","group":"准备动作"},{"text":"水开使用勺子舀出锅内 2 分之一菜汤（注意！不要将菜舀出）。","group":"准备动作"},{"text":"将所有面条平铺在菜的上方。","group":"准备动作"},{"text":"盖上锅盖，中火焖 5 分钟。","group":"准备动作"},{"text":"打开锅盖，将舀出的菜汤使用勺子，以每次一勺的量，均匀撒在面条上。","group":"准备动作"},{"text":"盖上锅盖，中火焖 3 分钟。","group":"准备动作"},{"text":"打开锅盖，将所有的蒜、味精均匀撒入。","group":"准备动作"},{"text":"使用筷子不断翻炒，将菜与肉均匀搅拌。","group":"准备动作"},{"text":"关火","group":"准备动作"}],"tips":["毛细（顾名思义，就像头发，其实就有点像细粉丝那样细）","细（这个比毛细粗点，跟香头一样）","二细（有点像一般的炒面条那样粗）","三细（比二细稍微粗点，吃起来像吃粗粉条，不过面如果拉的比较劲道的话，这个嚼起来感觉很有味）","韭叶（这鸡就像韭菜叶子一样宽）","大宽（就像吃麻辣烫的那个宽粉一样）"]},
{"id":"hanshibanfan","name":"韩式拌饭","category":"主食","categoryKey":"staple","emoji":"🍚","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/韩式拌饭/韩式拌饭.png","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1080 大卡","time":"45分钟","servings":"1-2人份","description":"韩式拌饭是一道色彩缤纷、口感丰富的韩国家常料理，甜辣酱汁包裹着米饭、蔬菜、牛肉和溏心蛋，拌匀后一口满足。多种蔬菜提供维生素和膳食纤维，牛肉和鸡蛋补充优质蛋白，营养均衡。制作简单但备菜步骤稍多，新手也能从容完成，从准备到上桌大约需要 45 分钟。","tags":["辣","下饭"],"ingredients":[{"name":"米饭","amount":"1 碗 (400g)","optional":false,"amountValue":1,"amountUnit":"碗"},{"name":"鸡蛋","amount":"1 颗","optional":false,"amountValue":1,"amountUnit":"颗"},{"name":"火锅牛肉卷","amount":"6 卷 60g","optional":false,"amountValue":60,"amountUnit":"g"},{"name":"豆芽","amount":"1 把 80g","optional":false,"amountValue":80,"amountUnit":"g"},{"name":"蘑菇","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"胡萝卜","amount":"1/4 根","optional":false,"amountValue":4,"amountUnit":"根"},{"name":"西葫芦","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"韩式辣酱","amount":"25ml","optional":false,"amountValue":25,"amountUnit":"ml"},{"name":"雪碧","amount":"2 瓶盖, 20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"芝麻","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"芝麻油","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"生抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"}],"steps":[{"text":"蔬菜清洗 切丝 放锅中翻炒 食材变软 便可称出","group":""},{"text":"煮水 等沸腾时 焯牛肉卷 只需煮熟 大概三分钟即可捞出","group":""},{"text":"煎[溏心蛋](../../breakfast/溏心蛋.md)","group":""},{"text":"将[米饭](../../staple/米饭/电饭煲蒸米饭.md)放在一个碗里 然后倒扣在大碗","group":""},{"text":"将准备好的蔬菜和肉卷依次绕圈放在米饭上面 将煎蛋放中间","group":""},{"text":"备酱汁","group":""},{"text":"10ml 韩式辣酱（甜辣口）+ 5ml 生抽 + 两瓶盖雪碧（减肥的话 可以放无糖雪碧）+ 10g 芝麻 + 5ml 芝麻油","group":""},{"text":"搅拌上述酱汁，可以再加生抽和盐","group":""},{"text":"将备好的酱汁倒在摆好盘的碗中","group":""}],"tips":["这是道非常简单的菜 过程会比较繁琐 但当将菜肉米饭酱汁搅拌起来吃会很满足","如果对外观有一定要求 可以用砂锅代替普通碗"]},
{"id":"henanzhengmiantiao","name":"河南蒸面条","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/河南蒸面条/河南蒸面条.png","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"3066 大卡","time":"","servings":"1-2人份","description":"河南蒸面条是源自河南的家常小吃，面条先蒸后炒再蒸，油润入味，口感劲道爽滑。五花肉和蒜薹提供丰富的蛋白质和膳食纤维，搭配主食带来均衡营养。制作步骤稍多一些，但对新手而言只要按顺序操作就能成功。从备料到出锅，总共约需 40 分钟。","tags":["辣","蒸","进阶挑战"],"ingredients":[{"name":"挂面","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"五花肉","amount":"350g","optional":false,"amountValue":350,"amountUnit":"g"},{"name":"蒜薹","amount":"150g","optional":false,"amountValue":150,"amountUnit":"g"},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"生抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"蚝油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"盐","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"鸡精","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"十三香","amount":"1g","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"葱","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"姜","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"蒜","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"料酒","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"麻油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"起锅加 7 成水，水开，上蒸篦子","group":"第一次蒸"},{"text":"将挂面，均匀铺开放置，淋 5ml 油并抹匀，蒸 15 分钟","group":"第一次蒸"},{"text":"将挂面和蒸篦子取出，放置一边，并倒掉锅中的水","group":"第一次蒸"},{"text":"五花肉，切成 2mm 厚度的肉片","group":"切菜"},{"text":"蒜薹，切成 3cm 段","group":"切菜"},{"text":"葱，切成 0.2cm 薄片","group":"切菜"},{"text":"姜，切成 1mm x 1mm x 3cm 的细丝","group":"切菜"},{"text":"蒜，放在砧板上拍碎，切成 1mm 的粒度","group":"切菜"},{"text":"起锅，烧干水分，加 3ml 食用油","group":"炒制"},{"text":"手持锅柄，摇晃锅，使食用油充分挂满锅的 2/3","group":"炒制"},{"text":"中火，加入肉片，翻炒 1 分钟","group":"炒制"},{"text":"加入葱姜蒜，料酒，继续翻炒 1 分钟","group":"炒制"},{"text":"将蒜薹段，放入锅中，翻炒 1 分钟","group":"炒制"},{"text":"开始调味，加入老抽、生抽、蚝油、盐、鸡精、十三香，翻炒 1 分钟","group":"炒制"},{"text":"加入 500ML 水，没过蔬菜，炖煮 1 分钟","group":"炒制"},{"text":"将蒸好的挂面放入，不断搅拌 3 分钟，待挂面全部均匀上色，关火","group":"炒制"},{"text":"将搅拌好的挂面和菜，全部倒入额外的盆中","group":"炒制"},{"text":"起锅，加冷水 7 成，放上蒸篦子，将拌好的面条和菜，均匀的铺在上面","group":"第二次蒸"},{"text":"水开后，大火烧 15 分钟，出锅","group":"第二次蒸"},{"text":"淋上 10g 的麻油，即可食用","group":"第二次蒸"}],"tips":["挂面的粗细与口感：","细的、圆的 （超市大部分都是这种，口感更加劲道）","宽的、扁的 （口感比较软）"]},
{"id":"hongyundoubanfan","name":"红芸豆拌饭","category":"主食","categoryKey":"staple","emoji":"🍚","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"1842 大卡","time":"","servings":"1-2人份","description":"这道北印度家常菜是旁遮普邦和德里地区的传统美食，番茄洋葱汤汁浓郁辛香，炖煮后红芸豆软糯入味，与热米饭拌食温暖饱腹。豆子富含蛋白质、膳食纤维和多种微量元素，营养均衡。做法简单，初学者也能轻松上手，全程制作约 40 分钟，但干豆需提前浸泡 8 小时。浓郁的家常滋味，有妈妈的味道。","tags":["辣","下饭"],"ingredients":[{"name":"干红芸豆","amount":"200g（提前浸泡 8 小时）","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"洋葱","amount":"2 个（约 200g），切碎","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"番茄","amount":"3 个（约 300g），切碎（或番茄酱 30ml）","optional":false,"amountValue":3,"amountUnit":"个"},{"name":"生姜","amount":"10g，磨碎","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"大蒜","amount":"4 瓣（约 12g），磨碎","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"青辣椒","amount":"1 根，切缝","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"食用油","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"月桂叶","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"姜黄粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"红辣椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"香菜粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"孜然粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"印度综合香料粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"盐","amount":"6g","optional":false,"amountValue":6,"amountUnit":"g"},{"name":"水","amount":"600ml","optional":false,"amountValue":600,"amountUnit":"ml"},{"name":"香菜叶","amount":"15g（装饰用）","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"大米","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"水","amount":"400ml","optional":false,"amountValue":400,"amountUnit":"ml"}],"steps":[{"text":"将干红芸豆用清水浸泡至少 8 小时（过夜），浸泡后体积会膨胀约两倍","group":"准备工作（提前 8 小时）"},{"text":"将浸泡好的红芸豆沥干","group":"煮红芸豆"},{"text":"**使用高压锅**：放入红芸豆和 600ml 水，盖好锅盖，大火上气后转中火，**压 15-20 分钟**，直至*豆子用手指可轻松压碎*","group":"煮红芸豆"},{"text":"**使用普通锅**：放入红芸豆和足量水，大火煮沸后转中火，**煮 60-90 分钟**，直至豆子完全软烂","group":"煮红芸豆"},{"text":"煮好后保留煮豆汤水，备用","group":"煮红芸豆"},{"text":"在炒锅中倒入 30ml 食用油，中火加热","group":"炒制咖喱"},{"text":"放入月桂叶 2 片，炸至*散出香味*（约 10 秒）","group":"炒制咖喱"},{"text":"放入切碎的洋葱，翻炒至*金棕色*（约 6-8 分钟）","group":"炒制咖喱"},{"text":"加入磨碎的生姜和大蒜，翻炒 1 分钟","group":"炒制咖喱"},{"text":"加入切碎的番茄，翻炒至*番茄完全软烂出油*（约 5 分钟）","group":"炒制咖喱"},{"text":"加入姜黄粉 3g、红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 6g","group":"炒制咖喱"},{"text":"翻炒 2 分钟，使香料与番茄融合","group":"炒制咖喱"},{"text":"将煮好的红芸豆连同汤水一起倒入锅中","group":"炒制咖喱"},{"text":"加入青辣椒，搅拌均匀","group":"炒制咖喱"},{"text":"大火煮沸后转小火，**炖 15-20 分钟**","group":"炒制咖喱"},{"text":"期间用铲子背面压碎一部分豆子，使汤汁变得*浓稠*","group":"炒制咖喱"},{"text":"加入印度综合香料粉 3g，搅拌均匀","group":"炒制咖喱"},{"text":"关火，撒上香菜叶","group":"炒制咖喱"},{"text":"将大米淘洗干净","group":"蒸米饭"},{"text":"放入电饭锅，加入 400ml 水","group":"蒸米饭"},{"text":"正常蒸煮即可","group":"蒸米饭"},{"text":"将米饭盛入盘中","group":"上菜"},{"text":"将红芸豆咖喱浇在米饭上或旁边","group":"上菜"},{"text":"可搭配洋葱沙拉和柠檬角","group":"上菜"}],"tips":["红芸豆必须煮熟透才能食用，未熟的红芸豆含有植物血凝素(Phytohaemagglutinin)，可能导致食物中毒。","在印度，Rajma Chawal 被认为是最有家的味道的食物，地位类似于中国的\"红烧肉配米饭\"。","如果想要更浓郁的口感，可以加入 30ml 淡奶油。","剩余的红芸豆咖喱冷藏保存可达 3-4 天，味道会更好。"]},
{"id":"huotuifantuan","name":"火腿饭团","category":"主食","categoryKey":"staple","emoji":"🍚","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/火腿饭团/饭团.png","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"665 大卡","time":"","servings":"1-2人份","description":"一道简单快手的日式风味饭团，咸香火腿搭配沙拉酱与海苔，口感丰富饱腹。富含碳水化合物、蛋白质和维生素，能快速补充能量。制作难度极低，新手也能轻松上手，从煮饭到完成大约只需 1 小时。","tags":["凉拌","进阶挑战"],"ingredients":[{"name":"火腿(100g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"米饭(125g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"水(90ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"冷冻青豆(30g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"冷冻玉米粒(30g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"海苔碎(10g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"喜欢的沙拉酱(20g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"}],"steps":[{"text":"将米饭和水放到电饭锅里，点击米饭模式，等待完成","group":""},{"text":"冷冻玉米粒和青豆放到锅里，加水没过所有食材，沸腾后静待 2 分钟后，捞出。","group":""},{"text":"火腿切成 1cm 的方块","group":""},{"text":"与此同时，加入 10ml 食用油，加入火腿翻炒至火腿上色","group":""},{"text":"将米饭，火腿，海苔碎，青豆，玉米粒，沙拉酱放入碗中，混合均匀即可","group":""},{"text":"装盘（如果有的话）","group":""}],"tips":["沙拉酱的程度可以根据个人口味酌情删减。","可以尝试混合沙拉酱。","参考资料：小红书 - 干饭选手又困了"]},
{"id":"jichuniunaimianbao","name":"基础牛奶面包","category":"主食","categoryKey":"staple","emoji":"🍞","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/基础牛奶面包/1-1成品.jpg","hasImage":true,"difficulty":5,"difficultyText":"★★★★★","calories":"2048 大卡","time":"200分钟","servings":"1-2人份","description":"这款基础牛奶面包通过酵头预发酵简化了传统面包的制作，成品奶香浓郁，质地松软。富含碳水化合物和蛋白质，能为身体提供能量。难度适中，适合烘焙新手尝试，全程大约需要 200 分钟。","tags":["甜","进阶挑战"],"ingredients":[{"name":"**酵头**","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"面粉","amount":"1 cup （盛一杯后用勺子挂掉多余的部分，不要晃动）","optional":false,"amountValue":null,"amountUnit":""},{"name":"30 ℃ 温水（以不烫手为宜）","amount":"1 cup","optional":false,"amountValue":null,"amountUnit":""},{"name":"酵母","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"盐","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"**面团**","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"面粉","amount":"2½ cup","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡蛋","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"糖或糖浆 ⅛ cup","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"奶制品 混合后共 ¼ cup （奶粉需要和水混合。）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"黄油或玉米油 ⅛ cup","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"谷朊粉 ¼ ~ ½ cup （可选）","amount":"","optional":true,"amountValue":null,"amountUnit":""},{"name":"香草精","amount":"3 g （可选）","optional":true,"amountValue":3,"amountUnit":"g"}],"steps":[{"text":"首先，将酵母和 ***30℃ 的温水*** 用刮刀或厨具混合均匀，静置 5 分钟。之后与面粉混合，搅拌均匀。此时的酵头应该是**特别粘稠**的面糊。","group":"酵头的制作"},{"text":"用布盖上面糊，将面糊放置到**温暖的地方**进行发酵，时长为 45 ~ 60 分钟。","group":"酵头的制作"},{"text":"最终的面糊应该是表面有很多气泡的且体积明显增大。","group":"酵头的制作"},{"text":"将剩下的原料全部与酵头用刮刀混合、搅拌。在搅拌时一定要刮壁，使其充分混合。在形成面团且没有干粉时，用干净的干燥的一只手按压面团，另一只手扶住容器，使其形成一个大的面团，然后倒在面板或硅胶垫上操作","group":"面团的制作"},{"text":"用手掌下部推开面团，然后对折再次推开，直至表面没有干粉结块。这时的面团还不是很光滑。","group":"面团的制作"},{"text":"使用喷壶将至少是当前面团三倍大的容器内喷上一层植物油（也可用手涂抹均匀），将面团放入并盖上布，发酵 1 小时。","group":"面团的制作"},{"text":"此时面团应该有原来的两倍大。在面板或硅胶垫上撒上薄薄的一层面粉（可以看见面板或硅胶垫的厚度即可），然后将面团拿出，用手压瘪面团排气。","group":"面团的制作"},{"text":"之后使用擀面杖，擀成 1 cm 的厚片。并紧实、不留空隙地从一边卷起来。","group":"面团的制作"},{"text":"然后旋转 90° ，重复步骤 4、步骤 5 。","group":"面团的制作"},{"text":"将面包整形，放到垫了硅油纸的烤盘或者涂抹油脂的模具内。注意接缝处朝下。","group":"面团的制作"},{"text":"在托盘或模具内，发酵 30 ~ 45 分钟 。","group":"面团的制作"},{"text":"于此同时，预热烤箱。","group":"面团的制作"},{"text":"在面包上用剪子或者刀划开几条缝作为面包的花纹。","group":"面团的制作"},{"text":"用刷子刷上蛋液。（可选）","group":"面团的制作"},{"text":"放入烤箱，上下火 180℃ 烤制 30 分钟，然后调 165 ℃ 再烤 10 分钟。","group":"面团的制作"},{"text":"放凉后装入食品袋内，可保存一个星期。冷冻可保存一个月。","group":"面团的制作"}],"tips":["1. 常见原料的换算（仅供参考）","| 体积 /cup |原料  |质量 /g   |","|:---------:|:----:|:-------:|","|1          |黄油  |227      |","|1          |面粉  |120      |","|1          |细砂糖|180 ~ 200|","|1          |粗砂糖|200 ~ 220|","|1          |糖粉  |130      |","|1          |碎干果|114      |","|1          |葡萄干|170      |","|1          |蜂蜜  |340      |","2. 如何保存多余的面包","可以把面包切片进行冷冻，在下次使用时可以放置到常温处等待回温，亦或是直接加热。但**千万不要放到冷藏区！** 在冷藏区面包的水分会迅速流失。","3. 推荐食用方式","a. 取一大块面包，上下一分为二。放入锅中小火加热（一般不需要加油，但如果希望脆皮可在面包表面涂抹黄油后再煎烤） 1 ~ 2 分钟。","b. 锅中用喷壶喷 3 ~ 4 泵油，大火烧至锅中微微冒烟，转最小火。","c. 然后下入一枚鸡蛋，盖盖子。等待 2 ~ 3 分钟。然后翻面再加热 2 ~ 3 分钟。","（这是流心蛋的做法，如需要全熟蛋，可在翻面前加入最多 1 ml 的水，转中小火，直至把水烧干。这样就得到了一个全熟蛋）","d. 将面包双面涂上喜欢的任何酱料，将鸡蛋夹在中间。","------------------------------------------"]},
{"id":"qieziroujianbing","name":"茄子肉煎饼","category":"主食","categoryKey":"staple","emoji":"🍖","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/茄子肉煎饼/茄子肉煎饼.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"904 大卡","time":"30分钟","servings":"1-2人份","description":"这道家常煎饼融合了腊肉的咸香与茄子的软糯，外皮酥脆、内里绵润，是一道充满乡土风味的米粉主食。它富含碳水化合物和优质蛋白质，茄子还能提供膳食纤维和维生素，荤素搭配营养均衡。制作难度中等，需要掌握面糊稠度和煎制火候，但初学者跟着步骤操作也能成功。从备料到出锅大约需要 30 分钟。","tags":["早餐"],"ingredients":[{"name":"米粉","amount":"250g","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"面粉","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"鸡蛋","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"煮熟的腊肉","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"茄子","amount":"1 根（约 10-15cm 长）","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"食盐","amount":"1-2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"将茄子去皮后切成片，将腊肉切成片，备用","group":""},{"text":"依次向盆中加入 250g 米粉（大米研磨成的粉）、50g 面粉和 1 个鸡蛋","group":""},{"text":"边用筷子搅拌，边加入清水（**清水用于调节粘稠度**），使米粉、面粉、鸡蛋混合成面糊,当面糊能够附着在茄片、肉片上而不掉落时停止加水，而后将所有茄片和肉片放入面糊中，用面糊充分包裹","group":""},{"text":"平底锅加入食用油**10-30ml**，开小火","group":""},{"text":"用筷子或勺子把裹了面糊的茄片、肉片放入锅中，先煎至两面金黄，再煎**3-6分钟**（**煎的过程中，食用油会变少，可再添加食用油**）","group":""},{"text":"撒盐，翻炒均匀，起锅装盘","group":""}],"tips":["用小火煎"]},
{"id":"jianyuhaitaiyumifan","name":"鲣鱼海苔玉米饭","category":"主食","categoryKey":"staple","emoji":"🐟","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/鲣鱼海苔玉米饭/米饭.jpg","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"383 大卡","time":"","servings":"1人份","description":"这是一道鲜香味美的日式简餐，米饭粒粒分明，融合了鲣鱼的咸鲜、海苔的酥香与玉米的甜脆。鲣鱼富含优质蛋白和 DHA，搭配海苔的矿物质和玉米的膳食纤维，营养均衡。做法非常简单，新手也能轻松完成，实际动手仅需 5 分钟，加上煮饭总共约 40 分钟即可享用。","tags":["新手友好"],"ingredients":[{"name":"鲣鱼海苔碎","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"玉米粒","amount":"80g/袋","optional":false,"amountValue":80,"amountUnit":"g"}],"steps":[{"text":"盛好米饭，放入玉米粒拌好","group":""},{"text":"放入鲣鱼海苔碎","group":""}],"tips":["使用米家小饭煲煮东北米的话，水没过米 3 毫米就行，太多水煮出来不是一粒一粒的饭"]},
{"id":"jiangbanqiaomaimian","name":"酱拌荞麦面","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/酱拌荞麦面/1.jpeg","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"475 大卡","time":"","servings":"1-2人份","description":"酱拌荞麦面酸甜可口、清凉爽滑，是一道简单快手的家常凉拌面。荞麦面富含膳食纤维和蛋白质，搭配黄瓜、胡萝卜增添清爽口感与维生素，营养均衡。只需煮面、切菜、拌入老干妈，几步搞定，对新手非常友好，一般约 20 分钟便可完成。冷藏后食用风味更佳。","tags":["新手友好"],"ingredients":[{"name":"荞麦面","amount":"100 g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"黄瓜","amount":"0.5 根","optional":false,"amountValue":0.5,"amountUnit":"根"},{"name":"红萝卜","amount":"0.5 根","optional":false,"amountValue":0.5,"amountUnit":"根"},{"name":"老干妈","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"}],"steps":[{"text":"荞麦面下冷水煮熟，8-10 分钟 后捞出沥干备用","group":""},{"text":"黄瓜、萝卜 切成小条","group":""},{"text":"将荞麦面、黄瓜、萝卜放入盘子，放上老干妈，搅拌","group":""}],"tips":["荞麦面沥干后可以放冰箱冰镇后口感更佳","配料可以根据个人喜好选择其他，例如虾仁、肉沫等","酱料可以根据个人喜欢选择其他，例如花生酱、芝麻酱等","荞麦面跟其他面条热量几乎一致，所以不适合作为减脂的主食"]},
{"id":"jiucaihezi","name":"韭菜盒子","category":"主食","categoryKey":"staple","emoji":"🥬","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"794 大卡","time":"2.5小时","servings":"1-2人份","description":"韭菜盒子是一道传统中式面点，外皮金黄酥脆，内馅鲜香多汁。韭菜搭配虾仁和鸡蛋，富含维生素与优质蛋白质。做法简单，对新手也很友好，从和面到出锅大约需要 2.5 小时。","tags":[],"ingredients":[{"name":"韭菜","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"虾仁","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"鸡蛋","amount":"3 枚","optional":false,"amountValue":3,"amountUnit":"枚"},{"name":"香油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"面粉","amount":"250g","optional":false,"amountValue":250,"amountUnit":"g"}],"steps":[{"text":"将面粉放入大碗中，加入水，搅拌成光滑的面团，静置 30 分钟。","group":""},{"text":"韭菜洗净切碎，加入打散的鸡蛋、5g 盐，搅拌均匀。","group":""},{"text":"将面团分成小剂子，擀成薄圆饼，包入韭菜、虾仁、鸡蛋液。","group":""},{"text":"热锅，加入食用油，放入包好的韭菜盒子，煎至两面金黄，约 3-4 分钟。","group":""},{"text":"盛盘，稍凉后即可享用。","group":""}],"tips":["制作时可根据个人口味添加豆腐干等配料。","注意煎制时火候，避免外焦内生。"]},
{"id":"kelechaofan","name":"可乐炒饭","category":"主食","categoryKey":"staple","emoji":"🍚","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"913 大卡","time":"","servings":"1-2人份","description":"这道菜以可乐替代糖调味，带来独特的焦香微甜风味，酱汁浓郁包裹粒粒米饭，属于创意家常炒饭。鸡蛋和火腿肠提供优质蛋白质与能量，搭配主食米饭，营养均衡管饱。操作步骤直观，适合新手尝试，一般 大约 20 分钟便可端上桌。","tags":["辣"],"ingredients":[{"name":"米饭","amount":"200 g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"可乐","amount":"160 ml","optional":false,"amountValue":160,"amountUnit":"ml"},{"name":"鸡蛋","amount":"3 个","optional":false,"amountValue":3,"amountUnit":"个"},{"name":"火腿肠","amount":"20-100 g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"油","amount":"25 ml","optional":false,"amountValue":25,"amountUnit":"ml"},{"name":"生抽","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽","amount":"7.5 ml（如果使用无糖可乐，追加 5 ml，如果不使用豆瓣酱，追加 5 ml）","optional":false,"amountValue":7.5,"amountUnit":"ml"},{"name":"豆瓣酱","amount":"7.5 ml","optional":false,"amountValue":7.5,"amountUnit":"ml"},{"name":"蚝油","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"葱花","amount":"5 g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"胡椒粉","amount":"1 g","optional":false,"amountValue":1,"amountUnit":"g"}],"steps":[{"text":"将锅烧热后，加入 25 ml 油，放两个鸡蛋，煎至底部完全凝固","group":""},{"text":"翻面，煎至两面完全凝固","group":""},{"text":"关火，将鸡蛋取出，剪成 2-5 cm² 的小块后放回锅中（也可以直接用锅铲铲碎）","group":""},{"text":"重新开火，倒入可乐、生抽、老抽、豆瓣酱、蚝油，搅拌均匀","group":""},{"text":"加热到锅内液体剩 1/3，倒入米饭和火腿肠翻炒","group":""},{"text":"翻炒均匀后，改小火，锅内食物中心挖一个洞，打入 1 个鸡蛋，盖上锅盖，焖 2 分钟","group":""},{"text":"开盖翻炒至第三颗鸡蛋熟透，撒上葱花和胡椒粉，出锅","group":""}],"tips":["含糖可乐口感更好","如果喜欢干一点，多炒一会儿","如果嫌麻烦，可以在第一步直接放 3 个鸡蛋，取消挖洞打另一个鸡蛋的步骤"]},
{"id":"kongqizhaguozhaoshaojifan","name":"空气炸锅照烧鸡饭","category":"主食","categoryKey":"staple","emoji":"🍗","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/空气炸锅照烧鸡饭/空气炸锅照烧鸡饭.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1854 大卡","time":"1小时","servings":"1-2人份","description":"这道日式照烧风味的鸡肉饭，甜咸酱汁浓郁，表层烘烤得略微焦脆，内里软嫩多汁，搭配米饭非常下饭。鸡肉和鸡蛋提供丰富的优质蛋白，不过酱油和糖的用量较多，更适合偶尔改善口味。做法简单，只需混合原料交给空气炸锅，新手也能轻松搞定，从准备到出锅大约需要 1 小时。","tags":["炸","进阶挑战"],"ingredients":[{"name":"鸡肉","amount":"900g","optional":false,"amountValue":900,"amountUnit":"g"},{"name":"酱油","amount":"100-125ml","optional":false,"amountValue":125,"amountUnit":"ml"},{"name":"糖","amount":"60-65g","optional":false,"amountValue":65,"amountUnit":"g"},{"name":"白醋","amount":"30-35ml","optional":false,"amountValue":35,"amountUnit":"ml"},{"name":"丽滋饼干（咸味曲奇可替代）","amount":"16 个(48g)","optional":false,"amountValue":16,"amountUnit":"个"},{"name":"鸡蛋","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"}],"steps":[{"text":"将酱油、糖和醋混合在一起,搅匀料汁备用","group":""},{"text":"另一个碗中加入鸡肉、鸡蛋、1/2 料汁和压碎的丽滋饼干。搅拌均匀","group":""},{"text":"空气炸锅用箔纸碗铺底，加入肉饼混合物，将剩余的料汁均匀的倒在上面","group":""},{"text":"**350°F(177°C)** 炸**40 分钟**。最好在米饭上食用","group":""},{"text":"在外观*呈金黄酥脆*后出锅，切块盛盘","group":""}],"tips":["米饭的做法参考电饭煲蒸米饭或煮锅蒸米饭","操作时，需要注意温度以免烫伤。","参考资料：库克美食教程:Air fryer Teriyaki Chicken Meatloaf"]},
{"id":"laozaoxiaotangyuan","name":"醪糟小汤圆","category":"主食","categoryKey":"staple","emoji":"🍲","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":2,"difficultyText":"★★","calories":"957 大卡","time":"","servings":"1人份","description":"醪糟小汤圆是一道香甜软糯的传统中式甜品，酒酿的微酸与糯米的绵滑交融，暖胃又舒心。它富含碳水化合物和少量 B 族维生素，能快速补充能量，也有助促进血液循环。做法毫无门槛，对新手特别友好，从烧水到出锅只需约 15 分钟，是一碗随时都能轻松完成的家常甜汤。","tags":["汤","新手友好"],"ingredients":[{"name":"水","amount":"300 毫升 * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"小汤圆","amount":"250 克 * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"醪糟","amount":"50 克 * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"枸杞","amount":"5 颗 * 份数","optional":false,"amountValue":5,"amountUnit":"颗"},{"name":"白糖","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"将水倒入锅中并煮沸","group":""},{"text":"放入小汤圆煮 8 分钟","group":""},{"text":"放入醪糟和枸杞再煮 2 分钟","group":""},{"text":"盛入碗中根据个人口味加入白糖并搅拌均匀","group":""},{"text":"吃","group":""}],"tips":["白糖的用量根据个人口味更改","若喜欢更浓的口感可以减少 100 毫升内的水","若喜欢软点的枸杞口感，可以将枸杞和小汤圆同时煮"]},
{"id":"laoganmabanmian","name":"老干妈拌面","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":1,"difficultyText":"★","calories":"502 大卡","time":"","servings":"1人份","description":"一道香辣开胃的家常快手面食，面条筋道裹满老干妈的豆豉辣香，酱油提鲜，简单却滋味十足。作为主食能快速补充碳水化合物和能量，辣椒素还有助促进食欲。制作毫无门槛，新手也能轻松驾驭，从烧水到出锅只需大约十 分钟。","tags":["新手友好"],"ingredients":[{"name":"水","amount":"1 升","optional":false,"amountValue":null,"amountUnit":""},{"name":"面量","amount":"120 克 * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"老干妈","amount":"15ml * 份数","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"酱油","amount":"5ml * 份数","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"将水倒入锅中并煮沸","group":""},{"text":"将面均匀放入锅中","group":""},{"text":"在煮的过程注意搅拌，避免面粘成一坨","group":""},{"text":"当用筷子挑起一根面且该面能自然地从筷子上滑落时再等 30 秒关火","group":""},{"text":"将面夹入碗中","group":""},{"text":"按照上面的计量放入老干妈和酱油","group":""},{"text":"用筷子将碗里的面、老干妈、酱油拌均匀","group":""},{"text":"吃","group":""}],"tips":[]},
{"id":"laoyouzhuroufen","name":"老友猪肉粉","category":"主食","categoryKey":"staple","emoji":"🥓","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/老友猪肉粉/老友猪肉粉.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"927 大卡","time":"","servings":"1-2人份","description":"老友猪肉粉酸辣鲜香，米粉爽滑，带着豆豉与酸笋特有的浓郁风味，是典型的南宁家常味。猪肉提供优质蛋白质，米粉则快速补充碳水能量。整体制作中等难度，需注意提前泡发米粉，熟练后大约四十分钟就能端上桌。","tags":["辣"],"ingredients":[{"name":"米粉（250g 记得","amount":"50 度的温水泡半小时）","optional":false,"amountValue":null,"amountUnit":""},{"name":"猪肉(50g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"酸笋(50g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"剁椒（15g 辣椒剁完后, 个人需求适当放。 ）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"豆豉(30g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"大蒜(10g)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒(10-20ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽(15ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"白糖（5g 如果不喜欢糖，可以考虑不放）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"米醋(5ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐(5ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"油(15ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生粉(15ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"胡椒粉(10ml)","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"全部猪肉用料酒、盐、生抽、生粉、胡椒粉倒在一个碗里调味，备用","group":""},{"text":"热锅不放油，下全部酸笋把水份炒干，炒干的酸笋中间留点空间","group":""},{"text":"放入 10ml - 15ml 食用油与全部大蒜、 剁椒、 豆豉到炒干的酸笋中间，全部推到中间炒出香味","group":""},{"text":"放入全部调味好的猪肉，持续放入 10ml 生抽炒一分钟","group":""},{"text":"放入 5ml 米醋、 10ml 生抽、450ml 清水一起煮开","group":""},{"text":"水煮开后，放入温水泡好的米粉，继续煮 3 分钟就可以盛盘","group":""}],"tips":["记得米粉必须是泡过的才好吃，没有泡过的话是很难吃的！"]},
{"id":"laobing","name":"烙饼","category":"主食","categoryKey":"staple","emoji":"🫓","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/烙饼/成品.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1185 大卡","time":"","servings":"1人份","description":"这道家常烙饼层次分明，外皮酥脆内里柔软，带着油酥的焦香，是北方餐桌上常见的主食。主要提供碳水化合物和能量，适合搭配菜肴一起食用。制作需要一点手法，尤其卷酥和擀饼环节，但跟着步骤操作并不难，新手也能掌握。从和面到烙好，大约需要 1 个小时。","tags":["进阶挑战"],"ingredients":[{"name":"面粉","amount":"400g","optional":false,"amountValue":400,"amountUnit":"g"},{"name":"热水","amount":"130ml（80 度）","optional":false,"amountValue":130,"amountUnit":"ml"},{"name":"冷水","amount":"130ml","optional":false,"amountValue":130,"amountUnit":"ml"}],"steps":[{"text":"将 400g 面粉倒入盆中，一半用凉水和面，一半用热水和面，搅拌成面絮，用手揉成团。用保鲜膜封起来，醒面 40 分钟","group":""},{"text":"离醒面完成时间还有 10 分钟时，请查看[小技巧](../../condiment/油酥.md)中的油酥做法（热油酥效果更好）","group":""},{"text":"醒好的面不用揉，稍微摁一下，用一横刀一竖刀将其分成四份。","group":""},{"text":"搓圆，擀开，擀成与电饼铛大小差不多的饼，取 1/4 的油酥，将饼表面涂抹均匀","group":""},{"text":"沿饼的半径切开，从外圈将其卷成圆锥形，然后将圆锥尾部捏好，防止油酥外漏。","group":""},{"text":"按压面饼圆锥尖的地方，将其压扁，然后再次擀成与电饼铛大小差不多的面饼（厚度约为 3mm）","group":""},{"text":"将电饼铛预热，涂上凉油（热锅凉油），将擀好的饼放入电饼铛中，将饼的上方也刷点油，涂抹均匀（锁住水分），盖上盖子","group":""},{"text":"大火烙一分钟，打开盖子，将饼翻个面再烙一分钟","group":""},{"text":"重复以上动作，完成饼的烙制","group":""}],"tips":[]},
{"id":"litiqiaoka","name":"利提巧卡","category":"主食","categoryKey":"staple","emoji":"🍚","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"1019 大卡","time":"60分钟","servings":"1-2人份","description":"利提巧卡是印度比哈尔邦的传统主食，由烤得金黄的麦球和烟熏风味的蔬菜泥组成，口感外脆内软，香气浓郁。烤鹰嘴豆粉馅料富含植物蛋白和膳食纤维，搭配茄子、番茄、土豆等蔬菜，营养丰富。制作需要和面、包馅、烤制以及处理蔬菜，步骤较多，对新手有一定挑战，全程大约需要 60 分钟完成。","tags":["辣","炸","烤","进阶挑战"],"ingredients":[{"name":"全麦面粉","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"烤鹰嘴豆粉","amount":"120g","optional":false,"amountValue":120,"amountUnit":"g"},{"name":"洋葱","amount":"1 个（约 80g），切极细碎","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"青辣椒","amount":"2 根，切极细碎","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"生姜","amount":"5g，磨碎","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"芥末油","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"柠檬汁","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"香菜叶","amount":"10g，切碎","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"孜然籽","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"芝麻","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"红辣椒粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"印度黑盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"温水 约","amount":"100ml（用于和面）","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"酥油","amount":"30g（烤好后涂抹用）","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"茄子","amount":"1 个（约 250g）","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"番茄","amount":"2 个（约 180g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"土豆","amount":"2 个（约 240g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"大蒜","amount":"4 瓣（约 12g）","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"青辣椒","amount":"1 根","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"芥末油","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"盐","amount":"4g","optional":false,"amountValue":4,"amountUnit":"g"},{"name":"香菜叶","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"在碗中混合烤鹰嘴豆粉 120g、切碎的洋葱、青辣椒、生姜","group":"制作利提馅料"},{"text":"加入孜然籽 3g、芝麻 5g、红辣椒粉 3g、印度黑盐 3g、盐 3g","group":"制作利提馅料"},{"text":"加入芥末油 15ml、柠檬汁 10ml、切碎的香菜叶","group":"制作利提馅料"},{"text":"充分混合均匀，馅料应呈松散但可捏合的状态，备用","group":"制作利提馅料"},{"text":"将全麦面粉 200g 放入大碗中","group":"制作利提面团"},{"text":"逐渐加入温水，边加边揉，揉成*光滑柔软*的面团","group":"制作利提面团"},{"text":"面团静置 **15 分钟**","group":"制作利提面团"},{"text":"将面团分成 8 个等大的小剂子","group":"制作利提面团"},{"text":"每个剂子用手压成一个直径约 8cm 的圆形面片（中间稍厚）","group":"制作利提面团"},{"text":"在面片中央放入约 15g 馅料","group":"制作利提面团"},{"text":"将面片四周收拢包住馅料，封口处捏紧，搓成圆球","group":"制作利提面团"},{"text":"烤箱预热至 200°C","group":"烤制利提"},{"text":"将利提放在烤盘上，烤 **25-30 分钟**，期间翻面一次，直至*表面金棕色且有裂纹*","group":"烤制利提"},{"text":"如果使用明火：将利提直接放在炭火或煤气灶小火上烤，不断翻转，直至*均匀焦黄*","group":"烤制利提"},{"text":"烤好后趁热将每个利提表面涂上酥油，使其*浸润吸收*","group":"烤制利提"},{"text":"将茄子、番茄、土豆放在明火上直接烤，或放入 200°C 烤箱烤 **20-25 分钟**，直至*外皮焦黑、内部完全软烂*","group":"制作巧卡"},{"text":"烤好后去皮，将茄子、番茄、土豆分别用叉子或手捣碎","group":"制作巧卡"},{"text":"将捣碎的蔬菜混合在一起","group":"制作巧卡"},{"text":"加入切碎的大蒜、青辣椒、盐 4g、芥末油 15ml","group":"制作巧卡"},{"text":"充分搅拌混合均匀","group":"制作巧卡"},{"text":"撒上香菜叶装饰","group":"制作巧卡"},{"text":"将利提摆盘，旁边放上巧卡蔬菜泥","group":"上菜"},{"text":"趁热食用，用手掰开利提蘸巧卡","group":"上菜"}],"tips":["烤鹰嘴豆粉(Sattu)是比哈尔邦的特色食材，营养价值极高，富含蛋白质和纤维。在中国可能较难购买，可以自制：将鹰嘴豆(Chana)干炒至深棕色后磨成粉。","传统的利提用牛粪饼火(Cow dung cake fire)烤制，赋予独特的烟熏风味。家用烤箱或明火可以替代。","芥末油是这道菜的灵魂，不建议替换。如果买不到芥末油，可以使用菜籽油作为次选。","利提巧卡是印度最古老的食物之一，据传已有数千年历史，是古代士兵的行军食粮。"]},
{"id":"liangfen","name":"凉粉","category":"主食","categoryKey":"staple","emoji":"🍜","color":"#FFD166","light":"#FFF7E2","image":"dishes/staple/凉粉/lf1.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"539 大卡","time":"","servings":"1人份","description":"凉粉是一道源自四川的传统小吃，口感冰凉爽滑，酸辣开胃，很适合夏天消暑。主要原料是豌豆淀粉，富含碳水化合物，能为身体快速补充能量。制作过程不算复杂，但需要耐心搅煮和长时间冷藏定型，对新手来说难度适中。从煮制到完成大约需要 3-4 小时，其中大部分是等待冷藏的时间，动手操作只需大约半 小时。","tags":["辣"],"ingredients":[{"name":"豌豆淀粉","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"大蒜","amount":"3 瓣","optional":false,"amountValue":3,"amountUnit":"瓣"},{"name":"小米辣","amount":"3 颗","optional":false,"amountValue":3,"amountUnit":"颗"},{"name":"辣椒粉","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"酱油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"醋","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"白糖","amount":"3ml","optional":false,"amountValue":3,"amountUnit":"ml"},{"name":"鸡精","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"花生碎","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"香菜","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"}],"steps":[{"text":"准备食材。","group":""},{"text":"把豌豆淀粉和水各 100 克混合搅拌。","group":""},{"text":"往锅中倒入 600g 水，大火煮开后转为小火。","group":""},{"text":"倒入淀粉水，边倒边不断的搅拌，搅拌到浓稠且色泽均匀。","group":""},{"text":"找一个容器，在容器中刷一层薄薄的食用油。","group":""},{"text":"将煮好的淀粉倒入容器中冷藏 2-4 小时。","group":""},{"text":"冷藏后取出，脱模，切条。","group":""},{"text":"大蒜和小米辣剁成沫，放上 10g 辣椒粉，5g 花生碎，热油搅拌均匀。","group":""},{"text":"再加入 10ml 酱油，10ml 醋，5g 白糖，3g 鸡精，3g 盐搅拌均匀。","group":""},{"text":"将调味料倒在凉粉上，然后撒上香菜即可。","group":""}],"tips":["参考: 制作凉粉的详细步骤"]},
{"id":"luosifen","name":"螺蛳粉","category":"主食","categoryKey":"staple","emoji":"🐚","color":"#FFD166","light":"#FFF7E2","image":null,"hasImage":false,"difficulty":1,"difficultyText":"★","calories":"1109 大卡","time":"","servings":"1人份","description":"螺蛳粉是广西柳州的特色小吃，汤鲜味浓，酸辣爽口，米粉软滑筋道。口味上融合了螺蛳汤的鲜美、酸笋的独特发酵风味和辣椒油的刺激，层次分明。作为主食，米粉提供充足碳水化合物，螺蛳肉包和配料带来一定蛋白质，酸笋则有助于开胃促消化。这道菜所需操作简单，只需按顺序煮熟米粉和调味即可，对新手非常友好。从烧水到出锅，最快约十分钟就能端上餐桌，适合快手解决一餐。","tags":["新手友好"],"ingredients":[{"name":"根据个人经验，一包袋装螺蛳粉足够一人一餐食（虽然看着很大包）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"水","amount":"1L","optional":false,"amountValue":1000,"amountUnit":"ml"}],"steps":[{"text":"锅中加水，将水烧开","group":""},{"text":"下米粉，煮 3-5 分钟，期间用筷子搅拌，防止米粉粘在一起","group":""},{"text":"下汤料包，按个人口味添加","group":""},{"text":"下一部分配料包，如木耳，花生，螺蛳（这部分配料需要煮一会才入味）","group":""},{"text":"下调味包，按个人口味添加","group":""},{"text":"搅拌后捞出，放入碗中","group":""},{"text":"下剩下的配料包，如酸笋，豆皮（这部分配料不适合被汤泡太久）","group":""},{"text":"享用美食","group":""}],"tips":["如果想要更有嚼劲的粉，可以缩短第二步煮粉的时间","如果想在螺蛳粉中添加炸蛋，请参考炸蛋的教程","配料的选择请依照个人口味"]}
];
